#!/usr/bin/env python3
"""
Customer Support Notes Cleaner

Reads a text file of customer support notes and produces a cleaned summary in JSON.
- Deduplicates notes case-insensitively
- Normalizes whitespace
- Preserves original order of first appearance
"""

import json
import sys


def normalize_whitespace(text):
    """Remove leading/trailing whitespace and collapse internal whitespace."""
    return ' '.join(text.split())


def clean_notes(input_file):
    """Process support notes file and return cleaned data."""
    seen = set()
    unique_notes = []

    with open(input_file, 'r') as f:
        for line in f:
            # Normalize whitespace
            normalized = normalize_whitespace(line)

            # Skip empty lines
            if not normalized:
                continue

            # Check for duplicates (case-insensitive)
            lower = normalized.lower()
            if lower not in seen:
                seen.add(lower)
                unique_notes.append(normalized)

    return {
        "source_file": input_file,
        "unique_notes_count": len(unique_notes),
        "notes": unique_notes
    }


def main():
    # Default input file
    input_file = "support_notes.txt"
    if len(sys.argv) > 1:
        input_file = sys.argv[1]

    # Output file
    output_file = "output.json"
    if len(sys.argv) > 2:
        output_file = sys.argv[2]

    result = clean_notes(input_file)

    with open(output_file, 'w') as f:
        json.dump(result, f, indent=2)

    print(f"Processed {result['unique_notes_count']} unique notes from '{input_file}'")
    print(f"Output written to '{output_file}'")


if __name__ == "__main__":
    main()
